import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';
import { spawnAoeServe } from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/tests/helpers/aoeServe.ts';
import { startAcpSession, replayFrames, script, endTurn, HOLD } from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/tests/helpers/acp.ts';
const { chromium, expect } = createRequire('/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/package.json')('@playwright/test');
const [currentBinary, baselineBinary] = process.argv.slice(2);
assert(currentBinary && baselineBinary);
const browser = await chromium.launch({ headless: true });
try {
 for (const [label, binary, promptId] of [
  ['current-null-prompt-id', currentBinary, null],
  ['current-explicit-prompt-id', currentBinary, 'explicit-late-attach-turn'],
  ['S3-before-A-null-prompt-id', baselineBinary, null],
 ] as const) {
  process.env.AOE_E2E_BINARY = binary;
  let serve;
  const page = await browser.newPage();
  const wire: unknown[] = [];
  let connection = 0;
  page.on('websocket', socket => {
   if (!socket.url().includes('/acp/ws')) return;
   const ordinal = ++connection;
   wire.push({ kind: 'socket-open', ordinal, url: socket.url() });
   socket.on('framereceived', ({ payload }) => {
    const text = typeof payload === 'string' ? payload : payload.toString('utf8');
    try { wire.push({ ordinal, message: JSON.parse(text) }); } catch { wire.push({ ordinal, unparsed: text }); }
   });
  });
  try {
   const started = await startAcpSession(async options => {
    serve = await spawnAoeServe({ ...options, workerIndex: 0, parallelIndex: 36 });
    return serve;
   }, { title: label, fakeAcpScript: script(endTurn({ sessionUpdate: 'tool_call', toolCallId: 'late-attach-tool', title: 'LATE_ATTACH_NATIVE_TOOL', kind: 'read', status: 'pending' }, HOLD)) });
   const id = started.sessionId;
   const prompt = await fetch(`${serve.baseUrl}/api/sessions/${id}/acp/prompt`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text: 'EXPLICIT_LATE_ATTACH_INPUT', ...(promptId ? { prompt_id: promptId } : {}) }) });
   assert(prompt.ok, `${label}: prompt ${prompt.status} ${await prompt.text()}`);
   await expect.poll(async () => JSON.stringify(await replayFrames(serve.baseUrl, id)), { timeout: 30000 }).toContain('LATE_ATTACH_NATIVE_TOOL');
   const replayBefore = await replayFrames(serve.baseUrl, id);
   await page.goto(`${serve.baseUrl}/session/${id}`);
   const card = page.getByRole('button', { name: 'LATE_ATTACH_NATIVE_TOOL', exact: true }).locator('xpath=ancestor::div[contains(@class,"rounded-md")][1]');
   await expect(card.getByText('running', { exact: true })).toBeVisible({ timeout: 15000 });
   await page.getByRole('button', { name: 'Stop', exact: true }).click({ timeout: 15000 });
   await expect(page.getByRole('textbox', { name: /^Send a message/ })).toBeVisible({ timeout: 15000 });
   const replayAfter = await replayFrames(serve.baseUrl, id);
   assert.equal(replayAfter.filter(frame => frame.event?.Stopped?.reason === 'cancelled').length, 1);
   const runningAfterCancel = await card.getByText('running', { exact: true }).isVisible();
   const stoppedAfterCancel = await card.getByText('stopped', { exact: true }).isVisible();
   const wireBeforeReload = structuredClone(wire);
   await page.reload();
   await expect(card.getByText('stopped', { exact: true })).toBeVisible({ timeout: 15000 });
   await expect(card.getByText('running', { exact: true })).toBeHidden();
   const nativeLog = readFileSync(join(serve.home, 'fake-acp.log'), 'utf8');
   assert.equal([...nativeLog.matchAll(/session\/cancel sessionId=/g)].length, 1);
   console.log('LATE_ATTACH_TERMINAL_RESULT', JSON.stringify({ label, binary, promptId, id, replayBefore, replayAfter, wireBeforeReload, wireAfterReload: wire, runningAfterCancel, stoppedAfterCancel, stoppedAfterReload: true, nativeCancel: 1, nativeLog }));
  } finally {
   await page.close();
   if (serve) await serve.stop();
   console.log('LATE_ATTACH_TERMINAL_CLEANUP_GREEN', label);
  }
 }
} finally { await browser.close(); }

