import assert from 'node:assert/strict';
import { spawnAoeServe } from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/tests/helpers/aoeServe.ts';
import { startAcpSession, replayFrames, script, endTurn, HOLD } from '/home/fraggle/src/agent-of-empires-git-worktrees/5052-web-verification/web/tests/helpers/acp.ts';
const [binary] = process.argv.slice(2);
assert(binary); process.env.AOE_E2E_BINARY = binary;
let serve;
let socket;
try {
 const started = await startAcpSession(async options => { serve = await spawnAoeServe({ ...options, workerIndex: 0, parallelIndex: 36 }); return serve; }, { title: 'S3 late cursor baseline', fakeAcpScript: script(endTurn({ sessionUpdate: 'tool_call', toolCallId: 'late-attach-tool', title: 'LATE_ATTACH_NATIVE_TOOL', kind: 'read', status: 'pending' }, HOLD)) });
 const id = started.sessionId;
 const prompt = await fetch(`${serve.baseUrl}/api/sessions/${id}/acp/prompt`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text: 'BASELINE_EXPLICIT_INPUT' }) });
 assert(prompt.ok);
 const wait = async predicate => { const deadline = Date.now() + 15000; while (!(await predicate())) { assert(Date.now() < deadline, 'observable deadline exceeded'); await new Promise(resolve => setTimeout(resolve, 20)); } };
 await wait(async () => JSON.stringify(await replayFrames(serve.baseUrl, id)).includes('LATE_ATTACH_NATIVE_TOOL'));
 const replayBefore = await replayFrames(serve.baseUrl, id);
 const since = Math.max(...replayBefore.map(frame => frame.seq));
 const wire = [];
 const url = serve.baseUrl.replace('http:', 'ws:') + `/sessions/${id}/acp/ws?since=${since}`;
 socket = new WebSocket(url);
 socket.addEventListener('message', event => wire.push(JSON.parse(String(event.data))));
 await wait(() => wire.some(frame => frame.kind === 'transcript_snapshot'));
 const cancel = await fetch(`${serve.baseUrl}/api/sessions/${id}/acp/cancel`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' });
 assert(cancel.ok, `cancel ${cancel.status} ${await cancel.text()}`);
 await wait(async () => (await replayFrames(serve.baseUrl, id)).some(frame => frame.event?.Stopped?.reason === 'cancelled'));
 const replayAfter = await replayFrames(serve.baseUrl, id);
 const terminalSeq = replayAfter.find(frame => frame.event?.Stopped?.reason === 'cancelled').seq;
 await wait(() => wire.some(frame => frame.kind === 'reduced_state' && frame.seq >= terminalSeq));
 console.log('S3_LATE_ATTACH_WIRE_RESULT', JSON.stringify({ binary, id, since, terminalSeq, cancelStatus: cancel.status, replayBefore, replayAfter, wire, limitation: 'Real S3 daemon/native peer and cursor WebSocket; no embedded frontend in this frozen binary. This proves backend bootstrap behaviour, not S3 browser presentation.' }));
} finally { if (socket) socket.close(); if (serve) await serve.stop(); console.log('S3_LATE_ATTACH_WIRE_CLEANUP_GREEN'); }
